SourceCode.Declaration:
using System.Collections.Generic;

/// <summary>
/// Route optimisation engine for the Dispatch Workbench.
/// Applies feasibility filters (fleet availability, vehicle capacity,
/// driver competency, time windows) and sequences drops using a
/// nearest-neighbour heuristic based on great-circle distance.
/// Swap the sequencing method with a real solver (e.g. Bing Maps / OR-Tools)
/// as needed.
/// </summary>
public class DispRouteOptimizer
{
    private const real EarthRadiusKm = 6371.0;
    private const real AvgSpeedKmH   = 45.0;
    private const int  ServiceMins   = 15;

    private TransDate dispatchDate;
    private InventLocationId originLocation;
    private real originLat;
    private real originLon;
}

Method.Source:
public void new(TransDate _dispatchDate, InventLocationId _originLocation)
{
    dispatchDate   = _dispatchDate;
    originLocation = _originLocation;
    this.resolveOrigin();
}

private void resolveOrigin()
{
    InventLocation  loc = InventLocation::find(originLocation);
    LogisticsPostalAddress addr = LogisticsLocationEntity::location2PostalAddress(loc.InventLocationLogisticsLocation);
    originLat = addr.Latitude;
    originLon = addr.Longitude;
}

/// <summary>Great-circle distance in km between two lat/long points.</summary>
public static real haversineKm(real _lat1, real _lon1, real _lat2, real _lon2)
{
    real toRad(real _deg)
    {
        return _deg * 3.14159265358979 / 180.0;
    }

    real dLat = toRad(_lat2 - _lat1);
    real dLon = toRad(_lon2 - _lon1);
    real a = sin(dLat / 2) * sin(dLat / 2)
           + cos(toRad(_lat1)) * cos(toRad(_lat2))
           * sin(dLon / 2) * sin(dLon / 2);
    real c = 2 * atan2(sqrt(a), sqrt(1 - a));
    return EarthRadiusKm * c;
}

/// <summary>Vehicles with capacity/competency compatible with the selected drops.</summary>
public DispVehicleTable findEligibleVehicles(
    real _totalWeightKg,
    real _totalVolumeM3,
    int  _dropCount,
    DispDriverCompetency _requiredCompetency)
{
    DispVehicleTable vehicle;
    while select vehicle
        where vehicle.Available          == NoYes::Yes
           && vehicle.MaxWeightKg        >= _totalWeightKg
           && vehicle.MaxVolumeM3        >= _totalVolumeM3
           && vehicle.MaxDrops           >= _dropCount
           && vehicle.RequiredCompetency <= _requiredCompetency
    {
        // Ensure the vehicle is not already booked on the same day.
        DispDispatchHeader booked;
        select firstonly RecId from booked
            where booked.VehicleId    == vehicle.VehicleId
               && booked.DispatchDate == dispatchDate
               && booked.DispatchStatus != DispDispatchStatus::Cancelled
               && booked.DispatchStatus != DispDispatchStatus::Completed;
        if (!booked.RecId)
        {
            return vehicle;
        }
    }
    return vehicle;
}

/// <summary>First available driver whose competency covers the required level.</summary>
public DispDriverTable findEligibleDriver(DispDriverCompetency _requiredCompetency)
{
    DispDriverTable driver;
    while select driver
        where driver.Available  == NoYes::Yes
           && driver.Competency >= _requiredCompetency
    {
        DispDispatchHeader booked;
        select firstonly RecId from booked
            where booked.DriverId     == driver.DriverId
               && booked.DispatchDate == dispatchDate
               && booked.DispatchStatus != DispDispatchStatus::Cancelled
               && booked.DispatchStatus != DispDispatchStatus::Completed;
        if (!booked.RecId)
        {
            return driver;
        }
    }
    return driver;
}

/// <summary>
/// Sequences the supplied pending orders using nearest-neighbour from origin,
/// honouring soft time-window ordering (earlier TimeWindowTo wins on ties).
/// Writes back into the temp buffer with DropSequence assigned.
/// </summary>
public void sequenceDrops(DispPendingOrderTmp _orders)
{
    DispPendingOrderTmp   candidate;
    DispPendingOrderTmp   sequenced;
    Set                   visited = new Set(Types::Int64);
    real                  curLat  = originLat;
    real                  curLon  = originLon;
    TimeOfDay             curTime = 8 * 3600; // 08:00 default start
    int                   seq     = 0;

    while (true)
    {
        int64  bestRec  = 0;
        real   bestDist = 999999.0;
        TimeOfDay bestWin = 0;

        while select candidate
            where candidate.Selected == NoYes::Yes
        {
            if (visited.in(candidate.RecId))
                continue;

            real d = DispRouteOptimizer::haversineKm(
                curLat, curLon, candidate.Latitude, candidate.Longitude);

            // Prefer feasible time window; penalise late arrivals.
            TimeOfDay arrival = curTime + real2int((d / AvgSpeedKmH) * 3600);
            real score = d;
            if (candidate.TimeWindowTo && arrival > candidate.TimeWindowTo)
            {
                score += 500; // heavy penalty for missing window
            }

            if (score < bestDist
                || (score == bestDist && candidate.TimeWindowTo < bestWin))
            {
                bestDist = score;
                bestRec  = candidate.RecId;
                bestWin  = candidate.TimeWindowTo;
            }
        }

        if (!bestRec)
            break;

        seq++;
        select forupdate sequenced where sequenced.RecId == bestRec;
        // Persist ordering via a "DropSequence-like" ghost: reuse Selected+flag,
        // or read it back by RecId order from the caller.
        // Here we simply track visited and rely on caller to iterate visited order.
        visited.add(bestRec);

        // Advance clock and cursor
        real leg = DispRouteOptimizer::haversineKm(
            curLat, curLon, sequenced.Latitude, sequenced.Longitude);
        curTime += real2int((leg / AvgSpeedKmH) * 3600) + ServiceMins * 60;
        curLat   = sequenced.Latitude;
        curLon   = sequenced.Longitude;
    }
}

/// <summary>
/// Materialises a dispatch header + lines from the selected pending orders,
/// after allocating an eligible vehicle and driver.
/// </summary>
public DispDispatchId createDispatch(DispPendingOrderTmp _orders)
{
    DispPendingOrderTmp   order;
    real  totWt = 0, totVol = 0;
    int   drops = 0;
    DispDriverCompetency maxComp = DispDriverCompetency::Standard;

    while select order where order.Selected == NoYes::Yes
    {
        totWt  += order.WeightKg;
        totVol += order.VolumeM3;
        drops++;
        if (order.RequiredCompetency > maxComp)
            maxComp = order.RequiredCompetency;
    }

    if (!drops)
        throw error("@DispatchWB:NoOrdersSelected");

    DispVehicleTable vehicle = this.findEligibleVehicles(totWt, totVol, drops, maxComp);
    if (!vehicle.RecId)
        throw error("@DispatchWB:NoVehicleAvailable");

    DispDriverTable driver = this.findEligibleDriver(maxComp);
    if (!driver.RecId)
        throw error("@DispatchWB:NoDriverAvailable");

    // Sequence drops in place
    this.sequenceDrops(_orders);

    ttsbegin;
    DispDispatchHeader header;
    header.DispatchId      = NumberSeq::newGetNumFromCode('Disp_1').num();
    header.DispatchDate    = dispatchDate;
    header.PlannedDeparture= 8 * 3600;
    header.VehicleId       = vehicle.VehicleId;
    header.DriverId        = driver.DriverId;
    header.DispatchStatus  = DispDispatchStatus::Allocated;
    header.TotalWeightKg   = totWt;
    header.TotalVolumeM3   = totVol;
    header.DropCount       = drops;
    header.OriginLocation  = originLocation;
    header.insert();

    int seq = 0;
    while select order where order.Selected == NoYes::Yes
    {
        seq++;
        DispDispatchLine line;
        line.DispatchId        = header.DispatchId;
        line.DropSequence      = seq;
        line.SalesId           = order.SalesId;
        line.CustAccount       = order.CustAccount;
        line.DeliveryPostCode  = order.DeliveryPostCode;
        line.DeliveryCity      = order.DeliveryCity;
        line.Latitude          = order.Latitude;
        line.Longitude         = order.Longitude;
        line.TimeWindowFrom    = order.TimeWindowFrom;
        line.TimeWindowTo      = order.TimeWindowTo;
        line.WeightKg          = order.WeightKg;
        line.VolumeM3          = order.VolumeM3;
        line.RequiredCompetency= order.RequiredCompetency;
        line.insert();
    }
    ttscommit;

    return header.DispatchId;
}

/// <summary>
/// Loads sales orders in the requested date window into the temp buffer.
/// A sales order is considered "needing dispatch" if it has an open
/// SalesLine with ShippingDateRequested inside the window and no linked
/// active DispDispatchLine.
/// </summary>
public static void loadPendingOrders(
    DispPendingOrderTmp _tmp,
    TransDate _fromDate,
    TransDate _toDate)
{
    delete_from _tmp;

    SalesTable       salesTable;
    SalesLine        salesLine;
    CustTable        custTable;
    LogisticsPostalAddress addr;

    while select firstOnly10 salesTable
        exists join salesLine
            where salesLine.SalesId == salesTable.SalesId
               && salesLine.SalesStatus == SalesStatus::Backorder
               && salesLine.ShippingDateRequested >= _fromDate
               && salesLine.ShippingDateRequested <= _toDate
        notexists join DispDispatchLine dl
            where dl.SalesId == salesTable.SalesId
    {
        custTable = CustTable::find(salesTable.CustAccount);
        addr      = LogisticsLocationEntity::location2PostalAddress(salesTable.DeliveryPostalAddress);

        _tmp.clear();
        _tmp.SalesId            = salesTable.SalesId;
        _tmp.CustAccount        = salesTable.CustAccount;
        _tmp.CustName           = custTable.name();
        _tmp.RequestedShipDate  = salesTable.ShippingDateRequested;
        _tmp.DeliveryPostCode   = addr.ZipCode;
        _tmp.DeliveryCity       = addr.City;
        _tmp.Latitude           = addr.Latitude;
        _tmp.Longitude          = addr.Longitude;
        _tmp.TimeWindowFrom     = 9  * 3600;
        _tmp.TimeWindowTo       = 17 * 3600;
        _tmp.WeightKg           = SalesTotals::construct(salesTable).calcSalesWeight();
        _tmp.VolumeM3           = 0;
        _tmp.RequiredCompetency = DispDriverCompetency::Standard;
        _tmp.Selected           = NoYes::No;
        _tmp.insert();
    }
}
